package features

//go:generate go run ../../tools/featuresgen -root ../..

import (
	"bytes"
	"fmt"
	"go/format"
	"path/filepath"
	"sort"
)

// GeneratedFile is where tools/featuresgen writes the discovered
// lists, relative to the module root.
const GeneratedFile = "pkg/features/zdiscovered.go"

// DiscoverAll runs both discovery passes against the module rooted at
// root and returns the names sorted, so the generated file is stable.
func DiscoverAll(root string) (opcodes, directives []string, err error) {
	opcodes, err = DiscoverOpcodes(filepath.Join(root, DiscoverProtocolFile))
	if err != nil {
		return nil, nil, err
	}
	directives, err = DiscoverDirectives(filepath.Join(root, DiscoverParserFile))
	if err != nil {
		return nil, nil, err
	}
	sort.Strings(opcodes)
	sort.Strings(directives)
	return opcodes, directives, nil
}

// RenderDiscovered returns the Go source of GeneratedFile for the given
// lists. tools/featuresgen writes it; a test regenerates it in memory
// and fails when the committed copy is stale.
func RenderDiscovered(opcodes, directives []string) ([]byte, error) {
	var b bytes.Buffer
	b.WriteString("// Code generated by tools/featuresgen from " +
		DiscoverParserFile + " and " + DiscoverProtocolFile + "; DO NOT EDIT.\n\n")
	b.WriteString("package features\n\n")
	b.WriteString("// BuiltinOpcodes are the control-protocol opcodes this build accepts.\n")
	b.WriteString("var BuiltinOpcodes = []string{\n")
	for _, n := range opcodes {
		fmt.Fprintf(&b, "\t%q,\n", n)
	}
	b.WriteString("}\n\n")
	b.WriteString("// BuiltinDirectives are the service-file directives this build accepts.\n")
	b.WriteString("var BuiltinDirectives = []string{\n")
	for _, n := range directives {
		fmt.Fprintf(&b, "\t%q,\n", n)
	}
	b.WriteString("}\n")
	return format.Source(b.Bytes())
}

// LoadBuiltin builds the Registry from the lists compiled into this
// binary, so the answer does not depend on where it runs from.
func LoadBuiltin() (*Registry, ReconcileReport) {
	return Load(BuiltinOpcodes, BuiltinDirectives)
}
